// Resizing a WebGL canvas clears its drawing buffer. Commit the latest size
// inside the frame that paints it, never between a paint and composition.
export function createFrameViewport(resize, paint) {
  let pending = null, width = 0, height = 0;
  return {
    request(nextWidth, nextHeight) {
      if (!(nextWidth > 0 && nextHeight > 0)) return;
      pending = { width: nextWidth, height: nextHeight };
    },
    render(time) {
      const next = pending;
      pending = null;
      if (next && (next.width !== width || next.height !== height)) {
        width = next.width;
        height = next.height;
        resize(width, height);
      }
      paint(time);
    },
  };
}
